  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mongodb\"\n  url      = env(\"MONGODB_URI\")\n}\n\nenum UserRole {\n  student\n  admin\n}\n\nenum UserStatus {\n  active\n  suspended\n  banned\n  deleted\n}\n\nenum ReportStatus {\n  Lost\n  Found\n  Claimed\n  Returned\n}\n\nenum ReportType {\n  lost\n  found\n}\n\nenum ReactionType {\n  like\n  helpful\n  interested\n}\n\nmodel User {\n  id              String                  @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name            String\n  email           String                  @unique\n  password        String\n  profileImage    String?\n  role            UserRole                @default(student)\n  status          UserStatus              @default(active)\n  suspendedUntil  DateTime?\n  createdAt       DateTime                @default(now())\n  updatedAt       DateTime                @updatedAt\n  lostItems       LostItem[]              @relation(\"LostItemOwner\")\n  foundItems      FoundItem[]             @relation(\"FoundItemFinder\")\n  comments        ItemComment[]\n  reactions       ItemReaction[]\n  sentMessages    ChatMessage[]\n  chatLinks       ReportChatParticipant[]\n  systemQueries   SystemQuery[]\n  termsQuizScore  Int?\n  termsQuizPassed Boolean                 @default(false)\n  termsAgreed     Boolean                 @default(false)\n  termsAgreedAt   DateTime?\n}\n\nmodel LostItem {\n  id           String       @id @default(auto()) @map(\"_id\") @db.ObjectId\n  itemName     String\n  category     String\n  color        String\n  description  String\n  dateLost     DateTime\n  locationLost String\n  image        String\n  ownerId      String       @db.ObjectId\n  owner        User         @relation(\"LostItemOwner\", fields: [ownerId], references: [id])\n  status       ReportStatus @default(Lost)\n  claimerName  String?\n  claimedAt    DateTime?\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n}\n\nmodel FoundItem {\n  id            String       @id @default(auto()) @map(\"_id\") @db.ObjectId\n  itemName      String\n  category      String\n  color         String\n  description   String\n  dateFound     DateTime\n  locationFound String\n  image         String\n  finderId      String       @db.ObjectId\n  finder        User         @relation(\"FoundItemFinder\", fields: [finderId], references: [id])\n  status        ReportStatus @default(Found)\n  claimerName   String?\n  claimedAt     DateTime?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n}\n\nmodel ItemComment {\n  id        String     @id @default(auto()) @map(\"_id\") @db.ObjectId\n  itemType  ReportType\n  itemId    String     @db.ObjectId\n  userId    String     @db.ObjectId\n  user      User       @relation(fields: [userId], references: [id])\n  content   String\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  @@index([itemType, itemId, createdAt])\n}\n\nmodel ItemReaction {\n  id           String       @id @default(auto()) @map(\"_id\") @db.ObjectId\n  itemType     ReportType\n  itemId       String       @db.ObjectId\n  userId       String       @db.ObjectId\n  user         User         @relation(fields: [userId], references: [id])\n  reactionType ReactionType\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  @@unique([itemType, itemId, userId])\n  @@index([itemType, itemId])\n}\n\nmodel ReportChat {\n  id           String                  @id @default(auto()) @map(\"_id\") @db.ObjectId\n  reportType   ReportType\n  reportId     String                  @db.ObjectId\n  isClosed     Boolean                 @default(false)\n  createdAt    DateTime                @default(now())\n  updatedAt    DateTime                @updatedAt\n  participants ReportChatParticipant[]\n  messages     ChatMessage[]\n\n  @@unique([reportType, reportId])\n}\n\nmodel ReportChatParticipant {\n  id     String     @id @default(auto()) @map(\"_id\") @db.ObjectId\n  chatId String     @db.ObjectId\n  userId String     @db.ObjectId\n  chat   ReportChat @relation(fields: [chatId], references: [id])\n  user   User       @relation(fields: [userId], references: [id])\n\n  @@unique([chatId, userId])\n}\n\nmodel ChatMessage {\n  id        String     @id @default(auto()) @map(\"_id\") @db.ObjectId\n  chatId    String     @db.ObjectId\n  senderId  String     @db.ObjectId\n  text      String\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n  chat      ReportChat @relation(fields: [chatId], references: [id])\n  sender    User       @relation(fields: [senderId], references: [id])\n\n  @@index([chatId, createdAt])\n}\n\nmodel ArchiveRecord {\n  id            String    @id @default(auto()) @map(\"_id\") @db.ObjectId\n  entityType    String\n  itemName      String\n  category      String\n  color         String?\n  description   String?\n  date          DateTime?\n  location      String?\n  image         String?\n  status        String?\n  reporterName  String?\n  reporterEmail String?\n  claimerName   String?\n  claimedAt     DateTime?\n  reason        String?\n  deletedBy     String?\n  deletedAt     DateTime  @default(now())\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@index([entityType, deletedAt])\n}\n\nmodel SystemQuery {\n  id          String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  title       String\n  description String\n  severity    String   @default(\"medium\")\n  category    String   @default(\"bug\")\n  status      String   @default(\"Open\")\n  reporterId  String   @db.ObjectId\n  reporter    User     @relation(fields: [reporterId], references: [id])\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([status, createdAt])\n  @@index([reporterId, createdAt])\n}\n",
